"""Inventory web API on aiohttp.web."""
import aiohttp
from aiohttp import web

routes = web.RouteTableDef()


@routes.get("/items")
async def list_items(request):
    kind = request.query.get("kind")
    items = [i for i in request.app["db"].values() if kind is None or i["kind"] == kind]
    return web.json_response({"items": sorted(items, key=lambda i: i["sku"])})


@routes.get("/items/{sku}")
async def get_item(request):
    item = request.app["db"].get(request.match_info["sku"])
    if item is None:
        raise web.HTTPNotFound(text="no such item")
    return web.json_response(item)


@routes.post("/items")
async def create_item(request):
    if not request.has_body:
        raise web.HTTPBadRequest(text="empty body")
    item = await request.json()
    request.app["db"][item["sku"]] = item
    return web.json_response(item, status=201)


@routes.get("/whoami")
async def whoami(request):
    header = request.headers.get("Authorization")
    if not header:
        raise web.HTTPUnauthorized(text="login required")
    return web.json_response({"user": aiohttp.BasicAuth.decode(header).login})


def make_app(items=()):
    app = web.Application()
    app["db"] = {i["sku"]: dict(i) for i in items}
    app.add_routes(routes)
    return app

