async def supplier_note(self, sku):
    """The supplier's note for an item, or None when it cannot be decoded."""
    async with self.session.get(f"{self.base_url}/notes/{sku}") as resp:
        try:
            return await resp.text()
        except UnicodeDecodeError:
            return None
